import{_ as s}from"./chunks/failure-clustering-fingerprint.B8ggWE9V.js";import{_ as o,C as a,o as n,c as i,j as t,a as l,E as d,ak as h}from"./chunks/framework.sV-XtlWr.js";const x=JSON.parse('{"title":"Failure clusters & the inbox","description":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing.","frontmatter":{"title":"Failure clusters & the inbox","description":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/failure-clusters.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/failure-clusters.html"}],["meta",{"property":"og:title","content":"Failure clusters & the inbox | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Failures that share an error fingerprint grouped into one cluster, triaged once from the failure inbox with an owner, a known issue and snoozing."}]]},"headers":[],"relativePath":"features/failure-clusters.md","filePath":"features/failure-clusters.md","lastUpdated":1790778634000}'),c={name:"features/failure-clusters.md"};function u(g,e,f,m,p,w){const r=a("Needs");return n(),i("div",null,[e[0]||(e[0]=t("h1",{id:"failure-clusters-the-inbox",tabindex:"-1"},[l("Failure clusters & the inbox "),t("a",{class:"header-anchor",href:"#failure-clusters-the-inbox","aria-label":'Permalink to "Failure clusters & the inbox"'},"​")],-1)),d(r,{reporter:""}),e[1]||(e[1]=h('<p>One root cause usually breaks several tests, run after run. Piwi groups failures by root cause into <strong>failure clusters</strong>, and Home turns them into a <strong>failure inbox</strong>: the problems you still owe a decision.</p><h2 id="how-failures-are-grouped" tabindex="-1">How failures are grouped <a class="header-anchor" href="#how-failures-are-grouped" aria-label="Permalink to &quot;How failures are grouped&quot;">​</a></h2><p>Failed executions that share the same <strong>error fingerprint</strong> join one cluster, so twenty stack traces read as <em>&quot;20 failures, 3 root causes&quot;</em>. Clustering is always on and needs no configuration.</p><ul><li>The fingerprint <strong>masks volatile fragments</strong> of the error: timeouts and other numbers, UUIDs and hashes, URLs and emails, the <em>expected</em> and <em>received</em> values of an assertion, and dynamic locator options such as the <code>{ name: &#39;…&#39; }</code> of a table row, wherever the error prints the locator. The locator target itself (the test id, the role) still tells different failures apart.</li><li>It is <strong>call-site agnostic</strong>: the failing stack frame is shown for context but does not split a cluster, so one root cause reached from several spec files stays one cluster.</li><li>The fingerprint is always computed from the error the cluster was created from, so an improved normalization regroups clusters in place and keeps their triage, notes and diagnoses.</li><li>A run&#39;s <strong>Tests</strong> tab can group its failures by cluster, each group with its triage status; the <code>get_failure_groups</code> <a href="/reference/mcp-tools.html#get_failure_groups">MCP tool</a> adds a <strong>worker-correlation</strong> flag: &quot;the app is broken&quot; versus &quot;worker 3 is misbehaving&quot;.</li></ul><figure><img src="'+s+'" alt="The fingerprint pipeline: a raw error is normalized, hashed and routed to one cluster"></figure><p>With an embedding model configured, near-duplicate clusters that the fingerprint keeps apart are merged too: see <a href="./ai-diagnosis.html#semantic-merging-optional">semantic merging</a>.</p><h2 id="the-failure-inbox" tabindex="-1">The failure inbox <a class="header-anchor" href="#the-failure-inbox" aria-label="Permalink to &quot;The failure inbox&quot;">​</a></h2><p>The <strong>Failure inbox</strong> on Home lists up to 50 open failure clusters across the projects you can see, most recently seen first. Each row shows the cluster&#39;s <strong>headline</strong>, its <strong>top clue</strong>, the <strong>owner or assignee</strong>, the <strong>affected-test count</strong>, when it was <strong>last seen</strong>, and only the exceptional <strong>badges</strong>, such as a regression on the default branch.</p><h3 id="queues" tabindex="-1">Queues <a class="header-anchor" href="#queues" aria-label="Permalink to &quot;Queues&quot;">​</a></h3><p>The inbox is split into queues, each with a live count, shareable in the URL as <code>?queue=</code>.</p><table tabindex="0"><thead><tr><th>Queue</th><th>What it holds</th></tr></thead><tbody><tr><td><strong>All open</strong></td><td>Every open, non-snoozed cluster.</td></tr><tr><td><strong>New</strong></td><td>Clusters first seen, or seen again, since you last opened the inbox (kept per browser).</td></tr><tr><td><strong>Mine</strong></td><td>Clusters whose assignee, or <code>piwi:owner</code> annotation, is you.</td></tr><tr><td><strong>Needs ticket</strong></td><td>Untracked default-branch clusters older than 2 days, by default; see <a href="./issue-tracking.html">issue tracking</a>.</td></tr><tr><td><strong>Regressions</strong></td><td>Clusters that regressed on the default branch and are still failing there.</td></tr><tr><td><strong>Fix didn&#39;t hold</strong></td><td>Clusters whose fix landed then regressed.</td></tr><tr><td><strong>Quarantine ready</strong></td><td>Quarantined clusters whose tests stopped failing.</td></tr><tr><td><strong>Merge suggestions</strong></td><td>Clusters in a pending merge suggestion (see <a href="./ai-diagnosis.html#semantic-merging-optional">semantic merging</a>).</td></tr></tbody></table><h3 id="triage-from-the-row-or-the-keyboard" tabindex="-1">Triage from the row or the keyboard <a class="header-anchor" href="#triage-from-the-row-or-the-keyboard" aria-label="Permalink to &quot;Triage from the row or the keyboard&quot;">​</a></h3><p>Every row can be triaged in place. Select a row with the mouse or <code>j</code> / <code>k</code>, then: <code>o</code> open, <code>r</code> resolve, <code>i</code> ignore, <code>q</code> quarantine the cluster&#39;s tests, <code>a</code> assign, <code>s</code> snooze, <code>l</code> link a known issue, <code>c</code> create a Jira issue (when a tracker is connected). <code>x</code> selects rows for a <strong>bulk bar</strong> that applies the same actions to all of them. Resolve, ignore, snooze and assign on one row can be undone for a few seconds. <a href="/reference/keyboard-shortcuts.html#failure-inbox">Keyboard shortcuts</a> lists every key.</p><p>Linking a known issue (<code>l</code>) pins a URL; with an <a href="/operate/integrations.html">issue tracker connected</a>, Jira links unfurl and stay in sync, and you can <strong><a href="/features/issue-tracking.html">file the issue from the failure</a></strong> (<code>c</code>).</p><h2 id="owners-and-assignees" tabindex="-1">Owners and assignees <a class="header-anchor" href="#owners-and-assignees" aria-label="Permalink to &quot;Owners and assignees&quot;">​</a></h2><p>A cluster&#39;s <strong>owner</strong> is derived, not stored: it comes from the failing test&#39;s <code>piwi:owner</code> annotation; the cluster page (not the inbox) falls back to the repository&#39;s <code>CODEOWNERS</code>. You can override it by <strong>assigning</strong> the cluster to a person: an assignee takes precedence over the derived owner, and the <strong>Mine</strong> queue matches either one against the signed-in user (by name or email, best effort).</p><h2 id="the-cluster-page" tabindex="-1">The cluster page <a class="header-anchor" href="#the-cluster-page" aria-label="Permalink to &quot;The cluster page&quot;">​</a></h2><p>A cluster page leads with the same situation block as a failing execution (<a href="/guide/first-failure.html">Your first failure</a>), across every test that shares the failure. The heading is the cluster&#39;s name (its <a href="./ai-diagnosis.html">AI title</a> when one exists), and three lines are specific to a cluster:</p><ul><li><strong>The occurrence sparkline</strong>: how often it failed across recent runs, <em>N occurrences in M tests over D · last X ago</em>.</li><li><strong>What changed</strong>: the commits and files between the last passing run (or your baseline) and this failure, with <strong>See the changes</strong> leading to the diff. When there is nothing to diff it says why and what would fix it (no passing run yet, runs that record no commit or repository URL, a host Piwi does not read, or a private repository without an <a href="/guide/source-control.html">SCM token</a>), and keeps what still works: the range on the host&#39;s <strong>Compare</strong> page, <strong>Copy git log</strong> for your own checkout, and <strong>Browse commits</strong> to pick a baseline. The same commit on both sides means the change is not in the code.</li><li><strong>The state line</strong>, below.</li></ul><p>The <strong>Affected tests</strong> list selects which test&#39;s latest execution the evidence shows. The diagnosis, the locator fix, verify and reproduce sit in the folded <a href="./fix-plans.html#more-ways-to-fix"><strong>More ways to fix</strong></a> toolbox.</p><h3 id="the-state-line" tabindex="-1">The state line <a class="header-anchor" href="#the-state-line" aria-label="Permalink to &quot;The state line&quot;">​</a></h3><p>The cluster page states where a cluster stands in <strong>one sentence with one verb</strong>, next to a colored dot: <em>still failing</em>, <em>not seen for N runs</em>, <em>fixed and verified, still open</em>, <em>stopped failing</em>, <em>ticket Done</em>, <em>regressed, the fix did not hold</em>, <em>resolved</em>, <em>ignored</em>, <em>snoozed</em> or <em>all tests quarantined</em>. When the runs or the tracker say an open cluster is done, the line offers the <strong>one action</strong> that reconciles them, <em>Mark resolved</em>; a snoozed cluster offers <em>Unsnooze</em>, an all-quarantined one <em>Release</em>. A regression reopens a resolved cluster on its own. Beside it, <strong>Triage</strong> sets the status (open / resolved / ignored), a note and the assignee, and snoozes the cluster for a day, a week or until it recurs.</p><h3 id="occurrences-over-time" tabindex="-1">Occurrences over time <a class="header-anchor" href="#occurrences-over-time" aria-label="Permalink to &quot;Occurrences over time&quot;">​</a></h3><p>A chart counts the cluster&#39;s failures per day, week or month, marking when its <strong>fix landed</strong>.</p><h2 id="did-the-fix-work" tabindex="-1">Did the fix work? <a class="header-anchor" href="#did-the-fix-work" aria-label="Permalink to &quot;Did the fix work?&quot;">​</a></h2><p>When a run executes every test a cluster covers and they all pass, Piwi records the fix: the run, the commit, and how long the cluster was open. Three verdicts, because they are not the same claim:</p><table tabindex="0"><thead><tr><th>Verdict</th><th>Means</th></tr></thead><tbody><tr><td><strong>Stopped failing</strong></td><td>The tests pass again. A flaky test can achieve this by accident.</td></tr><tr><td><strong>Diagnosis verified</strong></td><td>The commits since the last failing run touched a file the <a href="./ai-diagnosis.html#what-a-diagnosis-contains">suggested patch</a> named.</td></tr><tr><td><strong>Regressed</strong></td><td>A fix was recorded, and the cluster is failing again.</td></tr></tbody></table><p><strong>Every affected test must pass</strong>: a test that did not run counts against the fix. A filtered run can close a cluster if it covered all of it, so <code>--grep</code> over exactly the affected tests is enough.</p><p>The verdict moves the status only on strong evidence: <em>Diagnosis verified</em> sets an <strong>open</strong> cluster <strong>resolved</strong>, and <em>Regressed</em> sets a <strong>resolved</strong> one back to <strong>open</strong>, each adding a line to the triage note. <em>Stopped failing</em> alone changes nothing, and an <em>ignored</em> cluster is never touched. The <a href="./notifications.html">notifications</a> <code>cluster.fixed</code> and <code>cluster.regressed</code> follow the verdict, and with <a href="./pr-feedback.html">pull-request feedback</a> on, the comment gains a <strong>Fixed by this change</strong> section, even with <em>only comment on failures</em> set.</p><h2 id="snoozing" tabindex="-1">Snoozing <a class="header-anchor" href="#snoozing" aria-label="Permalink to &quot;Snoozing&quot;">​</a></h2><p><strong>Snoozing</strong> hides a cluster from every inbox queue without touching its status: it is still <em>open</em>. <strong>1 day</strong> and <strong>1 week</strong> return it when the deadline passes; <strong>Until it recurs</strong> returns it to the <strong>New</strong> queue, with a <strong>snoozed, back</strong> badge, when a new run fails it again.</p><h2 id="from-an-ai-agent" tabindex="-1">From an AI agent <a class="header-anchor" href="#from-an-ai-agent" aria-label="Permalink to &quot;From an AI agent&quot;">​</a></h2><p>Over the <a href="/features/mcp.html">MCP server</a>, <code>list_open_clusters</code> takes the same <code>queue</code> argument, and <code>set_cluster_status</code> triages.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/mass-failure.html">Triage a run gone red</a>: the clusters, used to collapse a red run into a few causes</li><li><a href="./ai-diagnosis.html">AI diagnosis</a>: an explanation of a cluster against your git diff</li><li><a href="./evidence.html">Failure evidence</a>: everything captured about one execution in the cluster</li><li><a href="/guide/concepts.html#error-fingerprint-failure-cluster">Core concepts</a>: fingerprint and failure cluster</li></ul>',35))])}const y=o(c,[["render",u]]);export{x as __pageData,y as default};
